steps:
3. MODIFY src/pages/PlannerLesson.jsx:

   a. Add to imports:
      import { Loader2 } from 'lucide-react';
      import { generateLessonPlan, generateAssessment } from '../services/ai';

   b. Add state at the top of the component (after existing state declarations):
      const [aiLoading, setAiLoading] = useState({});
      const [aiError, setAiError] = useState({});
      // aiLoading/aiError are keyed by step key: 'starter','mainLearning','plenary','evaluation','homework'

   c. Add helper function buildCurrContext() that converts currDetails to the shape expected by ai.js:
      function buildCurrContext() {
        if (!currDetails) return null;
        return {
          strand: currDetails.strand,
          subStrand: currDetails.subStrand,
          contentStandard: currDetails.contentStandard,
          indicators: currDetails.resolvedIndicators.length > 0
            ? currDetails.resolvedIndicators
            : currDetails.contentStandard.indicators,
        };
      }

   d. Add helper function handleGenerate(stepKey, aiAction):
      async function handleGenerate(stepKey, aiAction) {
        const ctx = buildCurrContext();
        if (!ctx) return;
        setAiLoading(l => ({ ...l, [stepKey]: true }));
        setAiError(e => ({ ...e, [stepKey]: null }));
        try {
          const result = await aiAction(ctx);
          setForm(f => ({ ...f, [stepKey]: result }));
        } catch (err) {
          setAiError(e => ({ ...e, [stepKey]: err.message }));
        } finally {
          setAiLoading(l => ({ ...l, [stepKey]: false }));
        }
      }

   e. Add AIButton component (small inline helper, defined above PlannerLesson or as a local const):
      function AIButton({ loading, disabled, onClick, children }) {
        return (
          <button
            type="button"
            onClick={onClick}
            disabled={disabled || loading}
            title={disabled ? 'Link this topic to a curriculum indicator first' : undefined}
            className="inline-flex items-center gap-1.5 rounded-full bg-accent/10 text-accent text-xs px-3 py-1 font-medium hover:bg-accent/20 disabled:opacity-40 disabled:cursor-not-allowed"
          >
            {loading ? <Loader2 size={12} className="animate-spin" /> : null}
            {children}
          </button>
        );
      }

   f. Modify each step's renderSlide() branch to insert an AIButton above the textarea:

      Starter step (current.key === 'starter'):
        - Before the textarea, insert:
          <AIButton
            loading={aiLoading.starter}
            disabled={!currDetails}
            onClick={() => handleGenerate('starter', async (ctx) => {
              const plan = await generateLessonPlan(ctx);
              return plan.starterActivity ?? '';
            })}
          >
            ✨ Generate Starter
          </AIButton>
        - Below textarea, if aiError.starter: <p className="text-xs text-red-500">{aiError.starter}</p>

      Main step (current.key === 'mainLearning'):
        - AIButton with label '✨ Generate Main Activity', onClick calls generateLessonPlan and takes plan.mainLearning.
        - Error display for aiError.mainLearning.

      Plenary step (current.key === 'plenary'):
        - AIButton with label '✨ Generate Plenary', onClick calls generateLessonPlan and takes plan.plenary.
        - Error display for aiError.plenary.

      Evaluation step (current.key === 'evaluation'):
        - AIButton with label '✨ Generate Assessment', onClick calls generateAssessment and returns the full string.
        - Error display for aiError.evaluation.

      Homework step (current.key === 'homework'):
        - AIButton with label '✨ Generate Homework', onClick calls generateLessonPlan and takes plan.homework.
        - Error display for aiError.homework.

      NOTE: For the three steps that share generateLessonPlan (starter, mainLearning, plenary, homework), each call makes a separate network request — this is correct and expected. No caching required.

      NOTE: The resource step does NOT get an AI button (no relevant AI function).
